"""Call metric SQL; scope fragments are generated by governance, never request text."""

def call_metric_queries(clause, old):
    base=f"FROM rx_integration_calls c JOIN rx_integrations a ON a.id=c.app_id AND a.tenant_id=c.tenant_id WHERE c.tenant_id=:t AND {clause} AND {old} AND c.created_at>=now()-make_interval(days=>:days)"
    stats=f'SELECT count(*) AS total,count(*) FILTER(WHERE c.status<400) AS successful,count(*) FILTER(WHERE c.status>=400) AS failed,round((percentile_cont(0.95) WITHIN GROUP(ORDER BY c.latency_ms))::numeric) AS p95_ms {base}'
    daily=f"SELECT to_char(c.created_at AT TIME ZONE 'Asia/Shanghai','YYYY-MM-DD') AS day,count(*) AS total,count(*) FILTER(WHERE c.status>=400) AS failed {base} GROUP BY 1 ORDER BY 1"
    apps=f"SELECT a.id,a.name,a.enabled,a.department_id,count(c.id) AS total,count(c.id) FILTER(WHERE c.status>=400) AS failed FROM rx_integrations a LEFT JOIN rx_integration_calls c ON c.app_id=a.id AND c.tenant_id=a.tenant_id AND c.created_at>=now()-make_interval(days=>:days) AND {old} WHERE a.tenant_id=:t AND {clause} GROUP BY a.id ORDER BY total DESC,a.name"
    recent=f'SELECT c.id,a.name AS app_name,c.operation,c.status,c.error_code,c.latency_ms,c.created_at {base} ORDER BY c.created_at DESC LIMIT 50'
    return {'stats':stats,'daily':daily,'apps':apps,'recent':recent}
